export function getTranslatedProduct(product, language = 'en') {
  if (!product) return product;
  if (language === 'en') return product;

  const pTrans = PRODUCT_TRANSLATIONS[product.id];
  if (pTrans && pTrans[language]) {
    const loc = pTrans[language];
    return {
      ...product,
      name: loc.name || product.name,
      description: loc.desc || product.description,
      process: loc.process || product.process,
      origin: loc.origin || product.origin
    };
  }

  // If specific translation entry not explicitly defined in map above, translate material category and preserve specs
  const matTerm = (MATERIAL_TERM_MAP[language] && MATERIAL_TERM_MAP[language][product.category]) || product.category;
  return {
    ...product,
    name: `${matTerm} · ${product.name}`,
    description: product.description
  };
}
